import React from "react";
import "./Update.css";
import { UpdatesData } from "../Data/Data";

const Updates = () => {
  return React.createElement(
    "div",
    { className: "Updates" },
    UpdatesData.map((update, index) =>
      React.createElement(
        "div",
        { className: "update", key: index },
        React.createElement("img", { src: update.img, alt: "profile" }),
        React.createElement(
          "div",
          { className: "noti" },
          React.createElement(
            "div",
            { style: { marginBottom: "0.5rem" } },
            React.createElement("span", null, update.name),
            React.createElement("span", null, ` ${update.noti}`)
          ),
          React.createElement("span", null, update.time)
        )
      )
    )
  );
};

export default Updates;
