import * as React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import Modal from "@mui/material/Modal";
import Box from "@mui/material/Box";
import "./Table.css";
import { motion } from "framer-motion";
import Lottie from "lottie-react";
import sparkles from "../assets/sparkle.json";
import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import CloseIcon from "@mui/icons-material/Close";
import EmojiObjectsOutlinedIcon from "@mui/icons-material/EmojiObjectsOutlined";
import LocalShippingOutlinedIcon from "@mui/icons-material/LocalShippingOutlined";
import WarningAmberIcon from "@mui/icons-material/WarningAmber";

function createData(name, trackingId, date, status) {
  return { name, trackingId, date, status };
}

const rows = [
  createData("Inventory Management System", 20345231, "15 March 2025", "Approved"),
  createData("E-commerce App", 20345232, "16 March 2025", "Pending"),
  createData("Hotel Booking Platform", 20345233, "18 March 2025", "Delivered"),
  createData("Custom ERP Solution", 20345234, "20 March 2025", "Approved"),
];

const makeStyle = (status) => {
  const base = {
    padding: "5px 14px",
    borderRadius: "30px",
    fontWeight: "600",
    fontSize: "0.85rem",
    animation: "shimmer 2s infinite",
    backgroundSize: "200% auto",
    backgroundClip: "text",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
  };

  if (status === "Approved") {
    return {
      ...base,
      backgroundImage: "linear-gradient(90deg, #ffb6c1, #ff69b4, #ffb6c1)",
    };
  } else if (status === "Pending") {
    return {
      ...base,
      backgroundImage: "linear-gradient(90deg, #ffd54f, #ffca28, #ffd54f)",
    };
  } else {
    return {
      ...base,
      backgroundImage: "linear-gradient(90deg, #81d4fa, #29b6f6, #81d4fa)",
    };
  }
};

export default function BasicTable() {
  const [open, setOpen] = React.useState(false);
  const [confirmOpen, setConfirmOpen] = React.useState(false);
  const [selectedOrder, setSelectedOrder] = React.useState(null);

  const handleOpen = (row) => {
    setSelectedOrder(row);
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setConfirmOpen(false);
  };

  const handleCancelOrder = () => {
    setConfirmOpen(true);
  };

  const confirmCancel = () => {
    console.log("Order cancelled:", selectedOrder);
    setConfirmOpen(false);
    setOpen(false);
  };

  return (
    <div className="Table">
      <h3>Recent Software Product Orders</h3>
      <TableContainer component={Paper} style={{ boxShadow: "0px 13px 20px 0px #80808029", borderRadius: "12px" }}>
        <Table sx={{ minWidth: 650 }} aria-label="simple table">
          <TableHead>
            <TableRow>
              <TableCell>Product</TableCell>
              <TableCell align="left">Tracking ID</TableCell>
              <TableCell align="left">Order Date</TableCell>
              <TableCell align="left">Status</TableCell>
              <TableCell align="left">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {rows.map((row) => (
              <TableRow
                key={row.name}
                sx={{ "&:last-child td, &:last-child th": { border: 0 }, "&:hover": { backgroundColor: "#f5f5f5" } }}
              >
                <TableCell component="th" scope="row">{row.name}</TableCell>
                <TableCell align="left">{row.trackingId}</TableCell>
                <TableCell align="left">{row.date}</TableCell>
                <TableCell align="left">
                  <span className="status" style={makeStyle(row.status)}>{row.status}</span>
                </TableCell>
                <TableCell align="left" className="Details" onClick={() => handleOpen(row)}>
                  View Details
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Detail Modal */}
      <Modal open={open} onClose={handleClose}>
        <Box sx={{
          position: "absolute",
          top: "52%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: 480,
          bgcolor: "rgba(255, 240, 245, 0.95)",
          borderRadius: "24px",
          boxShadow: "0 0 40px rgba(255, 192, 203, 0.5)",
          backdropFilter: "blur(10px)",
          p: 4,
          overflow: "hidden"
        }}>
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <Lottie
              animationData={sparkles}
              loop
              autoplay
              style={{
                width: 100,
                height: 100,
                position: 'absolute',
                top: '-20px',
                left: 'calc(50% - 50px)',
                zIndex: 10,
              }}
            />
            <div style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              borderBottom: "2px solid #ffc0cb",
              paddingBottom: "0.7rem",
              marginBottom: "1rem"
            }}>
              <h2 style={{ display: "flex", alignItems: "center", fontWeight: "600", fontSize: "1.4rem", color: "#d63384" }}>
                <InfoOutlinedIcon style={{ marginRight: "10px", color: "#ff69b4" }} />
                Order Info
              </h2>
              <CloseIcon onClick={handleClose} style={{ cursor: "pointer", color: "#d63384" }} />
            </div>

            {selectedOrder && (
              <div style={{ lineHeight: "1.8", fontSize: "1rem" }}>
                <p><strong style={{ color: "#ff4081" }}>Product:</strong> {selectedOrder.name}</p>
                <p><strong style={{ color: "#ff4081" }}>Tracking ID:</strong> {selectedOrder.trackingId}</p>
                <p><strong style={{ color: "#ff4081" }}>Order Date:</strong> {selectedOrder.date}</p>
                <p><strong style={{ color: "#ff4081" }}>Status:</strong>
                  <span style={makeStyle(selectedOrder.status)}>{selectedOrder.status}</span>
                </p>
                <div style={{
                  marginTop: "20px",
                  padding: "16px",
                  borderRadius: "20px",
                  background: "linear-gradient(145deg, #ffe4ec, #ffe4f0)",
                  boxShadow: "inset 0 0 12px #ffb6c1",
                  color: "#6b004b"
                }}>
                  <p style={{ display: "flex", alignItems: "center", marginBottom: "0.5rem" }}>
                    <EmojiObjectsOutlinedIcon style={{ marginRight: "8px", color: "#ff69b4" }} />
                    <strong>Description:</strong>&nbsp; Custom-designed software product with pastel UI, built for smooth client experiences.
                  </p>
                  <p style={{ display: "flex", alignItems: "center" }}>
                    <LocalShippingOutlinedIcon style={{ marginRight: "8px", color: "#ff69b4" }} />
                    <strong>Delivery ETA:</strong>&nbsp; 10 days from order date.
                  </p>
                </div>
                <div style={{
                  display: "flex",
                  gap: "10px",
                  marginTop: "1.5rem",
                  justifyContent: "center"
                }}>
                  <button onClick={handleCancelOrder} style={{
                    background: "white",
                    color: "#ff4d88",
                    padding: "10px 20px",
                    borderRadius: "25px",
                    border: "2px solid #ff4d88",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "0.3s",
                  }}>
                    Cancel Order
                  </button>
                </div>
              </div>
            )}
          </motion.div>
        </Box>
      </Modal>

      {/* Cancel Confirmation Modal */}
      <Modal open={confirmOpen} onClose={handleClose}>
        <Box sx={{
          position: "absolute",
          top: "55%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: 380,
          bgcolor: "white",
          borderRadius: "18px",
          p: 4,
          textAlign: "center",
          boxShadow: "0 0 30px rgba(255, 105, 180, 0.4)",
        }}>
          <WarningAmberIcon style={{ fontSize: 50, color: "#ff4d88" }} />
          <h2 style={{ margin: "20px 0 10px", color: "#b30059" }}>Are you sure?</h2>
          <p style={{ marginBottom: "20px", color: "#444" }}>Do you really want to cancel this order?</p>
          <div style={{ display: "flex", justifyContent: "center", gap: "15px" }}>
            <button onClick={handleClose} style={{
              background: "#ff4d88",
              color: "white",
              padding: "8px 20px",
              border: "none",
              borderRadius: "20px",
              fontWeight: "600",
              cursor: "pointer"
            }}>
              No
            </button>
            <button onClick={confirmCancel} style={{
              background: "white",
              color: "#ff4d88",
              padding: "8px 20px",
              border: "2px solid #ff4d88",
              borderRadius: "20px",
              fontWeight: "600",
              cursor: "pointer"
            }}>
              Yes, Cancel
            </button>
          </div>
        </Box>
      </Modal>
    </div>
  );
}
