import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Lottie from "lottie-react";
import loginAnimation from "../assets/login-lottie.json";
import axios from "axios";
import "./Login.css";

const Login = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = async () => {
    if (username && password) {
      try {
        // Make POST request to the login API
        const response = await axios.post("http://192.168.100.44:3004/api/login", {
          email: username,
          password: password,
        });

        // Check if login is successful (for example, if a token is returned)
        if (response.data.token) {
          localStorage.setItem("isAuthenticated", "true");
          localStorage.setItem("authToken", response.data.token);  // Store the auth token if available
          navigate("/dashboard");
        } else {
          alert("Login failed, please try again.");
        }
      } catch (error) {
        console.error("Error during login:", error);
        alert("Error logging in, please try again.");
      }
    } else {
      alert("Please enter username and password!");
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-bg">
        <div className="auth-card">
          <div className="auth-left">
            <div className="auth-heading">ODL Login</div>
            <div className="auth-animation">
              <Lottie animationData={loginAnimation} loop={true} />
            </div>
          </div>

          <div className="auth-right">
            <h2 className="auth-title">Welcome Back</h2>
            <p className="auth-subtitle">Sign in to continue</p>

            <div className="auth-form">
              <input
                type="email"
                placeholder="Email"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button onClick={handleLogin}>Login</button>
            </div>

            <div className="test-box">
              <h4>Test Credentials</h4>
              <p><strong>Email:</strong> testuser@example.com</p>
              <p><strong>Password:</strong> 123456</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
