import React from "react";
import CustomerReview from "../CustomerReviews/CustomerReview.js"
import Updates from "../Updates/Update.js";
import "./RightSide.css";

const RightSide = () => {
  return React.createElement(
    "div",
    { className: "RightSide" },
    React.createElement(
      "div",
      null,
      React.createElement("h3", null, "Customer Review"),
      React.createElement(Updates, null)
    ),
    React.createElement(
      "div",
      null,
      React.createElement("h3", null, "Update"),
      React.createElement(CustomerReview, null)
    )
  );
};

export default RightSide;
