import React, { useEffect, useState } from "react";
import axios from "axios";
import "./OurServices.css";

const OurServices = () => {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://192.168.100.44:3004/api/services")
      .then((res) => {
        setServices(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching services:", err);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div className="services-container">Loading services...</div>;
  }

  return (
    <div className="services-container">
      <h2 className="services-title">
        🚀 Our <span>Software Services</span>
      </h2>
      <p className="services-subtitle">
        Transforming ideas into digital solutions with cutting-edge technology.
      </p>

      <div className="services-grid">
        {services.length > 0 ? (
          services.map((service, index) => (
            <div className="service-card" key={index}>
              <div className="service-image">
                <img
                  src={`http://192.168.100.44:3004/${service.image.replace(/\\/g, "/")}`}
                  alt={service.name}
                />
              </div>
              <h3 className="service-title">{service.name}</h3>
              <p className="service-description">{service.shortDescription || service.description}</p>
            </div>
          ))
        ) : (
          <p>No services available at the moment.</p>
        )}
      </div>
    </div>
  );
};

export default OurServices;
