import React from "react";
import "./YourSubscriptions.css";
import { FaCheckCircle, FaTimesCircle, FaDollarSign } from "react-icons/fa";

const YourSubscriptions = () => {
  const activeSubscriptions = [
    {
      id: 1,
      name: "Premium Plan",
      price: "$29.99 / month",
      status: "Active",
      renewalDate: "April 25, 2025",
      description: "Enjoy full access to all features with premium support and an ad-free experience.",
    },
    {
      id: 2,
      name: "Business Plan",
      price: "$49.99 / month",
      status: "Ended",
      renewalDate: "May 10, 2025",
      description: "Best suited for teams and businesses. Get priority support and team collaboration features.",
    },
  ];

  const availableSubscriptions = [
    {
      id: 3,
      name: "Basic Plan",
      price: "$9.99 / month",
      description: "Ideal for beginners. Get access to limited features with standard support.",
      features: ["Limited Access", "No Ads", "Community Support"],
    },
    {
      id: 4,
      name: "Pro Plan",
      price: "$19.99 / month",
      description: "Unlock full access to all standard features with priority support and exclusive content.",
      features: ["Full Access", "Priority Support", "Exclusive Content"],
    },
    {
      id: 5,
      name: "Enterprise Plan",
      price: "$99.99 / month",
      description: "For large businesses. Enjoy custom solutions, advanced analytics, and 24/7 support.",
      features: ["All Features", "24/7 Support", "Custom Solutions"],
    },
  ];

  return (
    <div className="subscriptions-container">
      {/* Active Subscriptions Section */}
      <section className="active-subscriptions">
        <h2 className="section-title">
          Your <span>Subscriptions</span>
        </h2>
        <p className="section-subtitle">
          Manage your current subscriptions, renew them, or explore better plans.
        </p>
        <div className="subscription-grid">
          {activeSubscriptions.map((sub) => (
            <div key={sub.id} className="subscription-card active">
              <div className="ribbon">Active</div>
              <h3>{sub.name}</h3>
              <p className="price">{sub.price}</p>
              <p className="status">
                Status: <strong>{sub.status}</strong>
              </p>
              <p className="renewal">
                Next Renewal: <strong>{sub.renewalDate}</strong>
              </p>
              <p className="description">{sub.description}</p>
              <div className="btn-container">
                <button className="renew-btn">
                  <FaCheckCircle /> Renew
                </button>
                <button className="upgrade-btn">
                  <FaDollarSign /> Upgrade
                </button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Available Subscriptions Section */}
      <section className="available-subscriptions">
        <h2 className="section-title">
          Explore <span>More Plans</span>
        </h2>
        <p className="section-subtitle">
          Find a plan that best suits your needs and upgrade for a better experience.
        </p>
        <div className="subscription-grid">
          {availableSubscriptions.map((sub) => (
            <div key={sub.id} className="subscription-card available">
              <h3>{sub.name}</h3>
              <p className="price">{sub.price}</p>
              <p className="description">{sub.description}</p>
              <ul className="features">
                {sub.features.map((feature, index) => (
                  <li key={index}>
                    <FaCheckCircle /> {feature}
                  </li>
                ))}
              </ul>
              <button className="buy-btn">
                <FaDollarSign /> Buy Now
              </button>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default YourSubscriptions;
