import React, { useState } from "react";
import { FaPaperPlane, FaUser, FaRobot } from "react-icons/fa";
import "./Queries.css";

const Queries = () => {
  const [messages, setMessages] = useState([
    { text: "Hello! How can we assist you?", sender: "bot" },
  ]);
  const [input, setInput] = useState("");

  const sendMessage = () => {
    if (input.trim() === "") return;
    setMessages([...messages, { text: input, sender: "user" }]);
    setInput("");

    // Fake bot reply (optional)
    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        { text: "We received your query! Our team will respond soon.", sender: "bot" },
      ]);
    }, 1000);
  };

  return (
    <div className="chatbox-container">
      <div className="chatbox">
        <div className="chat-header">
          <h2>Chat With Us</h2>
        </div>
        <div className="chat-messages">
          {messages.map((msg, index) => (
            <div key={index} className={`message ${msg.sender}`}>
              {msg.sender === "user" ? <FaUser className="icon user-icon" /> : <FaRobot className="icon bot-icon" />}
              <p>{msg.text}</p>
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            type="text"
            placeholder="Type your message..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
          <button onClick={sendMessage}>
            <FaPaperPlane />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Queries;
