import { createElement } from "react";
import "./Cards.css";
import { cardsData } from "../Data/Data";
import Card from "../Card/Card";

const Cards = () => {
  return createElement(
    "div",
    { className: "Cards" },
    cardsData.map((card, id) =>
      createElement(
        "div",
        { className: "parentContainer", key: id },
        createElement(Card, {
          title: card.title,
          color: card.color,
          barValue: card.barValue,
          value: card.value,
          png: card.png,
          series: card.series,
        })
      )
    )
  );
};

export default Cards;
