import { createElement, useState } from "react";
import "./Card.css";
import { CircularProgressbar } from "react-circular-progressbar";
import "react-circular-progressbar/dist/styles.css";
import { motion, LayoutGroup } from "framer-motion";
import { UilTimes } from "@iconscout/react-unicons";
import Chart from "react-apexcharts";

// Parent Card Component
const Card = (props) => {
  const [expanded, setExpanded] = useState(false);

  return createElement(
    LayoutGroup,
    null,
    expanded
      ? createElement(ExpandedCard, { param: props, setExpanded: () => setExpanded(false) })
      : createElement(CompactCard, { param: props, setExpanded: () => setExpanded(true) })
  );
};

// Compact Card Component
function CompactCard({ param, setExpanded }) {
  const Png = param.png;

  return createElement(
    motion.div,
    {
      className: "CompactCard",
      style: { background: param.color.backGround, boxShadow: param.color.boxShadow },
      layoutId: "expandableCard",
      onClick: setExpanded
    },
    createElement(
      "div",
      { className: "radialBar" },
      createElement(CircularProgressbar, { value: param.barValue, text: `${param.barValue}%` }),
      createElement("span", null, param.title)
    ),
    createElement(
      "div",
      { className: "detail" },
      createElement(Png, null),
      createElement("span", null, `$${param.value}`),
      createElement("span", null, "Last 24 hours")
    )
  );
}

// Expanded Card Component
function ExpandedCard({ param, setExpanded }) {
  const data = {
    options: {
      chart: { type: "area", height: "auto" },
      dropShadow: { enabled: false, top: 0, left: 0, blur: 3, color: "#000", opacity: 0.35 },
      fill: { colors: ["#fff"], type: "gradient" },
      dataLabels: { enabled: false },
      stroke: { curve: "smooth", colors: ["white"] },
      tooltip: { x: { format: "dd/MM/yy HH:mm" } },
      grid: { show: true },
      xaxis: {
        type: "datetime",
        categories: [
          "2018-09-19T00:00:00.000Z",
          "2018-09-19T01:30:00.000Z",
          "2018-09-19T02:30:00.000Z",
          "2018-09-19T03:30:00.000Z",
          "2018-09-19T04:30:00.000Z",
          "2018-09-19T05:30:00.000Z",
          "2018-09-19T06:30:00.000Z"
        ]
      }
    }
  };

  return createElement(
    motion.div,
    {
      className: "ExpandedCard",
      style: { background: param.color.backGround, boxShadow: param.color.boxShadow },
      layoutId: "expandableCard"
    },
    createElement(
      "div",
      { style: { alignSelf: "flex-end", cursor: "pointer", color: "white" } },
      createElement(UilTimes, { onClick: setExpanded })
    ),
    createElement("span", null, param.title),
    createElement(
      "div",
      { className: "chartContainer" },
      createElement(Chart, { options: data.options, series: param.series, type: "area" })
    ),
    createElement("span", null, "Last 24 hours")
  );
}

export default Card;
