import React, { useEffect, useState } from "react";
import "./OurProducts.css";
import { motion } from "framer-motion";
import { UilTimes } from "@iconscout/react-unicons";

const OurProducts = () => {
  const [products, setProducts] = useState([]);
  const [selectedProduct, setSelectedProduct] = useState(null);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await fetch("http://192.168.100.44:3004/api/products");
        const data = await response.json();
        setProducts(data);
      } catch (error) {
        console.error("Failed to fetch products:", error);
      }
    };

    fetchProducts();
  }, []);

  return (
    <div className="products-container">
      <h2 className="section-title">
        🚀 Empower Your Business with <span>Our Software Solutions</span> 💻
      </h2>
      <p className="section-subtitle">
        Cutting-edge software products to streamline your business operations. 🌟
      </p>

      <div className="products-grid">
        {products.map((product) => (
          <motion.div
            key={product._id}
            className="product-card"
            whileHover={{ scale: 1.08 }}
            whileTap={{ scale: 0.95 }}
          >
            <img
              src={`http://192.168.100.44:3004/${product.images[0]}`}
              alt={product.name}
              className="product-image"
            />
            <div className="product-info">
              <h3>{product.name}</h3>
              <p className="description">{product.shortDescription}</p>
              <button className="view-btn" onClick={() => setSelectedProduct(product)}>
                View Details
              </button>
            </div>
          </motion.div>
        ))}
      </div>

      {selectedProduct && (
        <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
          <motion.div className="modal-content" initial={{ scale: 0.8 }} animate={{ scale: 1 }}>
            <button className="close-btn" onClick={() => setSelectedProduct(null)}>
              <UilTimes size="30" />
            </button>
            <img
              src={`http://192.168.100.44:3004/${selectedProduct.images[0]}`}
              alt={selectedProduct.name}
              className="modal-image"
            />
            <h3 className="modal-title">{selectedProduct.name}</h3>
            <p className="modal-description">{selectedProduct.description}</p>
            {selectedProduct.liveLink && (
              <a href={selectedProduct.liveLink} target="_blank" rel="noopener noreferrer">
                🔗 View Live
              </a>
            )}
          </motion.div>
        </motion.div>
      )}
    </div>
  );
};

export default OurProducts;
